    rodata_clear (ms_mem s) -> WIN s -> 10 <= n16 < 8191 ->
    tsafe (k (Z_to_bv 64 (stc n16)) s) P ->
    tsafe ((x <- m_size_to_class_big A_SIZE_CLASSES (Z_to_bv 64 n16) ;; k x) s) P.
