Fixpoint ctzf (fuel : nat) (v : Z) : Z :=
  match fuel with
  | O => 0
  | S f => if Z.odd v then 0 else 1 + ctzf f (v / 2)
  end.
Definition ctz32 (v : Z) : Z := ctzf 32 v.

Lemma land_double : forall a b (r t : bool),
  Z.land (2 * a + Z.b2z r) (2 * b + Z.b2z t) = 2 * Z.land a b + Z.b2z (r && t).
Proof.
