Lemma land_neg_low : forall n v, (0 < v < 2 ^ Z.of_nat n) ->
  Z.land v (2 ^ Z.of_nat n - v) = 2 ^ (ctzf n v) /\ 0 <= ctzf n v < Z.of_nat n /\
  Z.testbit v (ctzf n v) = true /\ (forall j, 0 <= j < ctzf n v -> Z.testbit v j = false).
Proof.
