Lemma ctz32_spec : forall v, 0 < v < 2^32 ->
  Z.land v (2^32 - v) = 2 ^ (ctz32 v) /\ 0 <= ctz32 v < 32 /\
  Z.testbit v (ctz32 v) = true /\ (forall j, 0 <= j < ctz32 v -> Z.testbit v j = false).
Proof.
