Lemma act_mask_words : forall fr a, 0 <= fr < 2^32 -> 0 <= a < 32 ->
  let act2 := w32 (2 ^ (a + 1)) in
  v_and (w32 fr) (v_subw w0 act2) = w32 (fr - fr mod 2^(a+1)) /\
  v_and (w32 fr) (v_addiw act2 (-1)) = w32 (fr mod 2^(a+1)) /\
